1	package mevwatch
2	
3	import (
4		"bufio"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"math"
10		"os"
11		"path/filepath"
12		"sort"
13		"strings"
14		"syscall"
15	)
16	
17	// Block is one validated, deduplicated input block. Swaps are kept in
18	// canonical order: exact duplicates removed, sorted by Index.
19	type Block struct {
20		ChainID     string
21		BlockHash   string
22		BlockNumber int64
23		Swaps       []Swap
24	}
25	
26	// ReportFinding is one risk conclusion inside a block report. Evidence
27	// carries the raw fields of every swap that participated in the judgment.
28	type ReportFinding struct {
29		Kind     string `json:"kind"`
30		Severity int    `json:"severity"`
31		TxHash   string `json:"txHash"`
32		Evidence []Swap `json:"evidence"`
33	}
34	
35	// Report is the archived per-block risk report. Version records the full
36	// rule parameters that produced the findings, so the report stays
37	// interpretable without the original rule definition.
38	type Report struct {
39		ChainID     string          `json:"chainId"`
40		BlockHash   string          `json:"blockHash"`
41		BlockNumber int64           `json:"blockNumber"`
42		SwapCount   int             `json:"swapCount"`
43		Version     RuleVersion     `json:"version"`
44		Findings    []ReportFinding `json:"findings"`
45	}
46	
47	// LineError pins a replay failure to a 1-based input line.
48	type LineError struct {
49		Line int
50		Err  error
51	}
52	
53	func (e *LineError) Error() string { return fmt.Sprintf("line %d: %v", e.Line, e.Err) }
54	func (e *LineError) Unwrap() error { return e.Err }
55	
56	// ErrBusy reports an archive locked by another process.
57	var ErrBusy = errors.New("archive is busy")
58	
59	// ErrUnknownBlock reports a query for a block that was never archived.
60	var ErrUnknownBlock = errors.New("unknown block")
61	
62	type blockID struct {
63		chainID   string
64		blockHash string
65	}
66	
67	// blockLine mirrors one input line. Pointers distinguish a missing field
68	// from an explicit zero value.
69	type blockLine struct {
70		ChainID     *string `json:"chainId"`
71		BlockHash   *string `json:"blockHash"`
72		BlockNumber *int64  `json:"blockNumber"`
73		Swaps       *[]Swap `json:"swaps"`
74	}
75	
76	func parseBlock(text string) (Block, error) {
77		var raw blockLine
78		dec := json.NewDecoder(strings.NewReader(text))
79		if err := dec.Decode(&raw); err != nil {
80			return Block{}, fmt.Errorf("invalid JSON: %w", err)
81		}
82		if dec.More() {
83			return Block{}, errors.New("invalid JSON: unexpected trailing data")
84		}
85		if raw.ChainID == nil || *raw.ChainID == "" {
86			return Block{}, errors.New("chainId must be a non-empty string")
87		}
88		if raw.BlockHash == nil || *raw.BlockHash == "" {
89			return Block{}, errors.New("blockHash must be a non-empty string")
90		}
91		if raw.BlockNumber == nil {
92			return Block{}, errors.New("blockNumber is required")
93		}
94		if *raw.BlockNumber < 0 {
95			return Block{}, fmt.Errorf("blockNumber must be non-negative, got %d", *raw.BlockNumber)
96		}
97		if raw.Swaps == nil {
98			return Block{}, errors.New("swaps must be an array")
99		}
100	
101		byTx := make(map[string]Swap)
102		byIndex := make(map[int]string)
103		swaps := []Swap{}
104		for i, s := range *raw.Swaps {
105			if s.TxHash == "" {
106				return Block{}, fmt.Errorf("swaps[%d]: TxHash must not be empty", i)
107			}
108			if s.Pool == "" {
109				return Block{}, fmt.Errorf("swaps[%d]: Pool must not be empty", i)
110			}
111			if s.Trader == "" {
112				return Block{}, fmt.Errorf("swaps[%d]: Trader must not be empty", i)
113			}
114			if s.In < 0 || s.Out < 0 || s.GasPrice < 0 || s.Index < 0 {
115				return Block{}, fmt.Errorf("swaps[%d]: In, Out, GasPrice and Index must be non-negative", i)
116			}
117			if prev, ok := byTx[s.TxHash]; ok {
118				if prev != s {
119					return Block{}, fmt.Errorf("swaps[%d]: conflicting records for tx %s", i, s.TxHash)
120				}
121				continue // exact duplicate, keep one copy
122			}
123			if other, ok := byIndex[s.Index]; ok {
124				return Block{}, fmt.Errorf("swaps[%d]: Index %d already used by tx %s", i, s.Index, other)
125			}
126			byTx[s.TxHash] = s
127			byIndex[s.Index] = s.TxHash
128			swaps = append(swaps, s)
129		}
130		sort.Slice(swaps, func(i, j int) bool { return swaps[i].Index < swaps[j].Index })
131		return Block{
132			ChainID:     *raw.ChainID,
133			BlockHash:   *raw.BlockHash,
134			BlockNumber: *raw.BlockNumber,
135			Swaps:       swaps,
136		}, nil
137	}
138	
139	func swapsEqual(a, b []Swap) bool {
140		if len(a) != len(b) {
141			return false
142		}
143		for i := range a {
144			if a[i] != b[i] {
145				return false
146			}
147		}
148		return true
149	}
150	
151	// sameContent reports whether two blocks carry the same content. Both sides
152	// are canonical (deduplicated, sorted by Index), so ordering and exact
153	// duplicates in the input do not affect the comparison.
154	func sameContent(blockNumber int64, swaps []Swap, b Block) bool {
155		return blockNumber == b.BlockNumber && swapsEqual(swaps, b.Swaps)
156	}
157	
158	// gasDominates reports whether front strictly exceeds victim*multiplier,
159	// staying correct when victim is zero or near math.MaxInt64.
160	func gasDominates(front, victim int64, multiplier int64) bool {
161		return victim <= math.MaxInt64/multiplier && front > victim*multiplier
162	}
163	
164	// DetectBlock checks every swap against its adjacent neighbours within its
165	// pool under the built-in rules. See DetectBlockWithRules.
166	func DetectBlock(swaps []Swap) []ReportFinding {
167		return DetectBlockWithRules(swaps, BuiltinVersion().Rules)
168	}
169	
170	// DetectBlockWithRules checks every swap against its adjacent neighbours
171	// within its pool: a sandwich when the same trader brackets the victim with
172	// higher gas on both sides, otherwise a displacement when the previous
173	// swap's gas strictly exceeds the configured multiple of the victim's. The
174	// last swap of a pool is checked too. An enabled sandwich takes priority
175	// over displacement for the same victim; with the sandwich rule off the
176	// victim can still be flagged for displacement. With both rules off the
177	// result is an empty slice.
178	func DetectBlockWithRules(swaps []Swap, rules RuleSet) []ReportFinding {
179		pools := make(map[string][]Swap)
180		for _, s := range swaps {
181			pools[s.Pool] = append(pools[s.Pool], s)
182		}
183		findings := []ReportFinding{}
184		for _, pool := range pools {
185			sort.Slice(pool, func(i, j int) bool { return pool[i].Index < pool[j].Index })
186			for i, victim := range pool {
187				var front, back *Swap
188				if i > 0 {
189					front = &pool[i-1]
190				}
191				if i+1 < len(pool) {
192					back = &pool[i+1]
193				}
194				if rules.Sandwich.Enabled && front != nil && back != nil &&
195					front.Trader == back.Trader && front.Trader != victim.Trader &&
196					front.GasPrice > victim.GasPrice && back.GasPrice > victim.GasPrice {
197					findings = append(findings, ReportFinding{
198						Kind: "sandwich", Severity: rules.Sandwich.Severity, TxHash: victim.TxHash,
199						Evidence: []Swap{*front, victim, *back},
200					})
201					continue
202				}
203				if rules.Displacement.Enabled && front != nil &&
204					gasDominates(front.GasPrice, victim.GasPrice, int64(rules.Displacement.Multiplier)) {
205					findings = append(findings, ReportFinding{
206						Kind: "displacement", Severity: rules.Displacement.Severity, TxHash: victim.TxHash,
207						Evidence: []Swap{*front, victim},
208					})
209				}
210			}
211		}
212		sort.Slice(findings, func(i, j int) bool {
213			if findings[i].Severity != findings[j].Severity {
214				return findings[i].Severity > findings[j].Severity
215			}
216			return findings[i].TxHash < findings[j].TxHash
217		})
218		return findings
219	}
220	
221	// record is the archived form of a block: the report plus the canonical
222	// swaps, so a later import can detect content conflicts. Version carries
223	// the full rule parameters used for the findings; it is nil only in
224	// archives written before rule versions existed, which are interpreted
225	// under the built-in rules.
226	type record struct {
227		ChainID     string          `json:"chainId"`
228		BlockHash   string          `json:"blockHash"`
229		BlockNumber int64           `json:"blockNumber"`
230		Swaps       []Swap          `json:"swaps"`
231		Findings    []ReportFinding `json:"findings"`
232		Version     *RuleVersion    `json:"version,omitempty"`
233	}
234	
235	func (r record) id() blockID { return blockID{r.ChainID, r.BlockHash} }
236	
237	func (r record) ruleVersion() RuleVersion {
238		if r.Version != nil {
239			return *r.Version
240		}
241		return BuiltinVersion()
242	}
243	
244	func (r record) report() Report {
245		return Report{
246			ChainID:     r.ChainID,
247			BlockHash:   r.BlockHash,
248			BlockNumber: r.BlockNumber,
249			SwapCount:   len(r.Swaps),
250			Version:     r.ruleVersion(),
251			Findings:    r.Findings,
252		}
253	}
254	
255	const (
256		archiveFileName = "archive.json"
257		lockFileName    = "lock"
258	)
259	
260	type archiveData struct {
261		Records []record `json:"records"`
262		// Versions and EnabledVersion are absent in archives written before
263		// rule versions existed; such archives run the built-in rules.
264		Versions       []RuleVersion `json:"versions,omitempty"`
265		EnabledVersion string        `json:"enabledVersion,omitempty"`
266	}
267	
268	func readArchive(dir string) (archiveData, error) {
269		raw, err := os.ReadFile(filepath.Join(dir, archiveFileName))
270		if errors.Is(err, os.ErrNotExist) {
271			return archiveData{Records: []record{}}, nil
272		}
273		if err != nil {
274			return archiveData{}, err
275		}
276		var data archiveData
277		if err := json.Unmarshal(raw, &data); err != nil {
278			return archiveData{}, fmt.Errorf("archive is corrupted: %w", err)
279		}
280		return data, nil
281	}
282	
283	// writeArchiveAtomic replaces the archive file in one rename, so a crash
284	// can only expose the previous or the next complete commit, never a half
285	// written file.
286	func writeArchiveAtomic(dir string, data archiveData) error {
287		raw, err := json.MarshalIndent(data, "", "  ")
288		if err != nil {
289			return err
290		}
291		tmp := filepath.Join(dir, archiveFileName+".tmp")
292		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o644)
293		if err != nil {
294			return err
295		}
296		if _, err := f.Write(raw); err != nil {
297			f.Close()
298			os.Remove(tmp)
299			return err
300		}
301		if err := f.Sync(); err != nil {
302			f.Close()
303			os.Remove(tmp)
304			return err
305		}
306		if err := f.Close(); err != nil {
307			os.Remove(tmp)
308			return err
309		}
310		if err := os.Rename(tmp, filepath.Join(dir, archiveFileName)); err != nil {
311			os.Remove(tmp)
312			return err
313		}
314		if d, err := os.Open(dir); err == nil {
315			d.Sync()
316			d.Close()
317		}
318		return nil
319	}
320	
321	// lockArchive takes an flock on the archive's lock file. The lock is
322	// released automatically if the process dies, so no stale locks survive.
323	func lockArchive(dir string, how int) (*os.File, error) {
324		f, err := os.OpenFile(filepath.Join(dir, lockFileName), os.O_CREATE|os.O_RDWR, 0o644)
325		if err != nil {
326			return nil, err
327		}
328		if err := syscall.Flock(int(f.Fd()), how); err != nil {
329			f.Close()
330			if errors.Is(err, syscall.EWOULDBLOCK) {
331				return nil, ErrBusy
332			}
333			return nil, err
334		}
335		return f, nil
336	}
337	
338	type parsedBlock struct {
339		line  int
340		block Block
341	}
342	
343	func parseBlocks(r io.Reader) ([]parsedBlock, error) {
344		var out []parsedBlock
345		reader := bufio.NewReader(r)
346		lineNo := 0
347		for {
348			raw, err := reader.ReadBytes('\n')
349			if len(raw) > 0 {
350				lineNo++
351			}
352			if text := strings.TrimSpace(string(raw)); text != "" {
353				block, perr := parseBlock(text)
354				if perr != nil {
355					return nil, &LineError{Line: lineNo, Err: perr}
356				}
357				out = append(out, parsedBlock{line: lineNo, block: block})
358			}
359			if err == io.EOF {
360				return out, nil
361			}
362			if err != nil {
363				return nil, err
364			}
365		}
366	}
367	
368	// ReplayFile imports the line-delimited blocks in inputPath into the
369	// archive at dir and returns one report per distinct block, in order of
370	// first appearance. New blocks are judged under the archive's currently
371	// enabled rule version.
372	func ReplayFile(inputPath, dir string) ([]Report, error) {
373		return replayFile(inputPath, dir, "")
374	}
375	
376	// ReplayFileWithVersion is ReplayFile under an explicitly registered rule
377	// version instead of the archive's enabled one.
378	func ReplayFileWithVersion(inputPath, dir, versionID string) ([]Report, error) {
379		if versionID == "" {
380			return nil, errors.New("version id must not be empty")
381		}
382		return replayFile(inputPath, dir, versionID)
383	}
384	
385	func replayFile(inputPath, dir, versionID string) ([]Report, error) {
386		f, err := os.Open(inputPath)
387		if err != nil {
388			return nil, err
389		}
390		defer f.Close()
391		return doReplay(f, dir, versionID)
392	}
393	
394	// Replay parses, validates and archives blocks from r under the archive's
395	// currently enabled rule version. Every line is checked before anything is
396	// written; any failure leaves the archive untouched. New reports are
397	// committed together in a single atomic write.
398	func Replay(input io.Reader, dir string) ([]Report, error) {
399		return doReplay(input, dir, "")
400	}
401	
402	// ReplayWithVersion is Replay under an explicitly registered rule version
403	// instead of the archive's enabled one.
404	func ReplayWithVersion(input io.Reader, dir, versionID string) ([]Report, error) {
405		if versionID == "" {
406			return nil, errors.New("version id must not be empty")
407		}
408		return doReplay(input, dir, versionID)
409	}
410	
411	func doReplay(input io.Reader, dir, versionID string) ([]Report, error) {
412		parsed, err := parseBlocks(input)
413		if err != nil {
414			return nil, err
415		}
416	
417		// Collapse repeated identities within this file, keeping first
418		// appearance order; conflicting content rejects the whole file.
419		type occurrence struct {
420			block Block
421			line  int
422		}
423		order := []occurrence{}
424		firstSeen := make(map[blockID]int)
425		for _, p := range parsed {
426			id := blockID{p.block.ChainID, p.block.BlockHash}
427			if first, ok := firstSeen[id]; ok {
428				if !sameContent(order[first].block.BlockNumber, order[first].block.Swaps, p.block) {
429					return nil, &LineError{Line: p.line, Err: fmt.Errorf(
430						"block %s/%s conflicts with line %d", id.chainID, id.blockHash, order[first].line)}
431				}
432				continue
433			}
434			firstSeen[id] = len(order)
435			order = append(order, occurrence{block: p.block, line: p.line})
436		}
437	
438		if err := os.MkdirAll(dir, 0o755); err != nil {
439			return nil, err
440		}
441		lock, err := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
442		if err != nil {
443			return nil, err
444		}
445		defer lock.Close()
446	
447		data, err := readArchive(dir)
448		if err != nil {
449			return nil, err
450		}
451		// Resolve the version once, while the exclusive lock is held: every
452		// new block in this run is judged under the same rules even if another
453		// process enables a different version right after we finish.
454		version, err := resolveReplayVersion(data, versionID)
455		if err != nil {
456			return nil, err
457		}
458		archived := make(map[blockID]int, len(data.Records))
459		for i, rec := range data.Records {
460			archived[rec.id()] = i
461		}
462	
463		reports := make([]Report, 0, len(order))
464		changed := false
465		for _, occ := range order {
466			id := blockID{occ.block.ChainID, occ.block.BlockHash}
467			if idx, ok := archived[id]; ok {
468				rec := data.Records[idx]
469				if !sameContent(rec.BlockNumber, rec.Swaps, occ.block) {
470					return nil, &LineError{Line: occ.line, Err: fmt.Errorf(
471						"block %s/%s conflicts with the archived record", id.chainID, id.blockHash)}
472				}
473				// Identical re-import: return the original report, add nothing.
474				reports = append(reports, rec.report())
475				continue
476			}
477			rec := record{
478				ChainID:     occ.block.ChainID,
479				BlockHash:   occ.block.BlockHash,
480				BlockNumber: occ.block.BlockNumber,
481				Swaps:       occ.block.Swaps,
482				Findings:    DetectBlockWithRules(occ.block.Swaps, version.Rules),
483				Version:     &version,
484			}
485			archived[id] = len(data.Records)
486			data.Records = append(data.Records, rec)
487			reports = append(reports, rec.report())
488			changed = true
489		}
490		if changed {
491			if err := writeArchiveAtomic(dir, data); err != nil {
492				return nil, err
493			}
494		}
495		return reports, nil
496	}
497	
498	// resolveReplayVersion picks the rule version for one replay run: the
499	// explicitly requested one, or the archive's currently enabled version.
500	func resolveReplayVersion(data archiveData, versionID string) (RuleVersion, error) {
501		if versionID != "" {
502			return findVersion(data, versionID)
503		}
504		return data.enabledVersion()
505	}
506	
507	// Query returns the archived report for one block identity. It only reads
508	// the archive; the original input file is not needed.
509	func Query(dir, chainID, blockHash string) (Report, error) {
510		if _, err := os.Stat(dir); err != nil {
511			if errors.Is(err, os.ErrNotExist) {
512				return Report{}, ErrUnknownBlock
513			}
514			return Report{}, err
515		}
516		lock, err := lockArchive(dir, syscall.LOCK_SH)
517		if err != nil {
518			return Report{}, err
519		}
520		defer lock.Close()
521	
522		data, err := readArchive(dir)
523		if err != nil {
524			return Report{}, err
525		}
526		for _, rec := range data.Records {
527			if rec.ChainID == chainID && rec.BlockHash == blockHash {
528				return rec.report(), nil
529			}
530		}
531		return Report{}, ErrUnknownBlock
532	}
533

