33		if r.ChainID != "1" || r.BlockHash != "0xa" || r.BlockNumber != 10 {
34			t.Fatalf("bad identity: %+v", r)
35		}
36		if r.SwapCount != 3 {
37			t.Fatalf("SwapCount = %d, want 3", r.SwapCount)
38		}
39		if len(r.Findings) != 1 {
40			t.Fatalf("got %d findings, want 1", len(r.Findings))
41		}
42		f := r.Findings[0]
43		if f.Kind != "sandwich" || f.Severity != 3 || f.TxHash != "0xvictim" {
44			t.Fatalf("bad finding: %+v", f)
45		}
46		if len(f.Evidence) != 3 {
47			t.Fatalf("evidence has %d swaps, want 3", len(f.Evidence))
48		}
49		wantOrder := []string{"0xfront", "0xvictim", "0xback"}
50		for i, want := range wantOrder {
51			if f.Evidence[i].TxHash != want {
52				t.Fatalf("evidence[%d].TxHash = %s, want %s", i, f.Evidence[i].TxHash, want)
53			}
54		}
55		if f.Evidence[0].GasPrice != 90 || f.Evidence[1].Trader != "user" || f.Evidence[2].In != 480 {
56			t.Fatalf("evidence lost raw fields: %+v", f.Evidence)
57		}
