125			`{"chainId":"1","blockHash":"0xe","blockNumber":20,"swaps":[{"TxHash":"0xs2","Pool":"p","Trader":"b","In":3,"Out":4,"GasPrice":6,"Index":1},{"TxHash":"0xs1","Pool":"p","Trader":"a","In":1,"Out":2,"GasPrice":5,"Index":0}]}` + "\n"
126		reports := replay(t, dir, input)
127		if len(reports) != 1 {
128			t.Fatalf("permuted duplicate block produced %d reports, want 1", len(reports))
129		}
130		if reports[0].SwapCount != 2 {
131			t.Fatalf("SwapCount = %d, want 2 after dedup", reports[0].SwapCount)
132		}
133		data, err := readArchive(dir)
134		if err != nil {
135			t.Fatal(err)
136		}
137		if len(data.Records) != 1 {
138			t.Fatalf("archive holds %d records, want 1", len(data.Records))
139		}
140	}
141	
142	func TestReplayEmptySwapsAndBlankLines(t *testing.T) {
143		dir := t.TempDir()
144		input := "\n  \n{\"chainId\":\"1\",\"blockHash\":\"0xf\",\"blockNumber\":1,\"swaps\":[]}\n\n"
145		reports := replay(t, dir, input)
146		if len(reports) != 1 {
