func TestGenerateAlertsIdempotent(t *testing.T) {
	dir := t.TempDir()
	mustReplay(t, dir, twoFindingsInput)

	first, err := GenerateAlerts(dir, "1", "ops", 10, 10, 3)
	if err != nil {
		t.Fatal(err)
	}
	if len(first) != 1 {
		t.Fatalf("first run: got %d, want 1", len(first))
	}
	// Repeated generation, wider range, overlapping range, and a "restart"
	// (fresh call against the same on-disk archive) create nothing new.
	for _, bounds := range [][2]uint64{{10, 10}, {0, 100}, {5, 15}, {10, 10} {
		again, err := GenerateAlerts(dir, "1", "ops", bounds[0], bounds[1], 1)
		if err != nil {
			t.Fatal(err)
		}
		if len(again) != 0 {
			t.Fatalf("range %d-%d re-generated %d records: %+v", bounds[0], bounds[1], len(again), again)
		}
	}
	// Re-importing the same block still cannot make it alert twice.
	mustReplay(t, dir, twoFindingsInput)
	again, err := GenerateAlerts(dir, "1", "ops", 0, 100, 1)
	if err != nil {
		t.Fatal(err)
	}
	if len(again) != 1 {
		t.Fatalf("after re-import got %d new records, want 1 (the displacement never processed)", len(again))
	}
	if again[0].Finding.Kind != "displacement" {
		t.Fatalf("the only new record should be the displacement, got %+v", again[0])
	}
}

